// InsertAll inserts records in bulk (demo data, imports): multi-row INSERT statements, one
// round trip per batch instead of one per record. With runTrigger every record's OnInsert
// trigger runs first, as Insert(true) would; the first failure stops before anything is
// written. Records are written with the receiver's database and company. Errors are
// *tables.BatchInsertError (Index = the record in records). Use it in a transaction: a
// failed batch leaves the earlier batches written.
func (t *UserPersonalization) InsertAll(records []*UserPersonalization, runTrigger bool) error {
	rows := make([][]interface{}, 0, len(records))
	for i, r := range records {
		r.triggerErr = nil
		if runTrigger {
			if err := r.runOnInsert(); err != nil {
				r.triggerErr = err
				return &tables.BatchInsertError{Index: i, Trigger: true, Err: err}
			}
		}
		rows = append(rows, []interface{}{
			r.User_id,
			r.Light_theme,
			r.Dark_theme,
			r.Mode,
			r.Wallpaper,
			r.Wallpaper_opacity,
			r.Wallpaper_blur,
			r.Panel_opacity,
			r.Font,
			r.Font_size,
			r.Density,
			r.Updated_at,
		})
	}
	tableName := UserPersonalizationTableName
	columns := []string{"user_id", "light_theme", "dark_theme", "mode", "wallpaper", "wallpaper_opacity", "wallpaper_blur", "panel_opacity", "font", "font_size", "density", "updated_at"}
	return tables.InsertRows(t.exec(), t.dbType, tableName, columns, rows)
}

// Modify updates the record in the database
func (t *UserPersonalization) Modify(runTrigger bool) bool {
	// OnModify trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnModify(); err != nil {
			fmt.Printf("Error: OnModify trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// A changed primary key is a rename: run the OnRename trigger
	// before it is written; xRec values are available through OldValue
	keyChanged := false
	if t.oldValues != nil {
		if t.hasFieldChanged("user_id") {
			keyChanged = true
		}
	}
	if runTrigger && keyChanged {
		if err := t.runOnRename(); err != nil {
			fmt.Printf("Error: OnRename trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := UserPersonalizationTableName

	// Build dynamic SQL based on field tracking
	var setClauses []string
	var values []interface{}

	// If we have old values (loaded from Get), only update changed fields.
	// Changed primary key fields are renamed in place (Rename): they are SET to the
	// new value while the WHERE clause matches the old one.
	if t.oldValues != nil {
		if t.hasFieldChanged("user_id") {
			setClauses = append(setClauses, "user_id = ?")
			values = append(values, t.User_id)
		}
		if t.hasFieldChanged("light_theme") {
			setClauses = append(setClauses, "light_theme = ?")
			values = append(values, t.Light_theme)
		}
		if t.hasFieldChanged("dark_theme") {
			setClauses = append(setClauses, "dark_theme = ?")
			values = append(values, t.Dark_theme)
		}
		if t.hasFieldChanged("mode") {
			setClauses = append(setClauses, "mode = ?")
			values = append(values, t.Mode)
		}
		if t.hasFieldChanged("wallpaper") {
			setClauses = append(setClauses, "wallpaper = ?")
			values = append(values, t.Wallpaper)
		}
		if t.hasFieldChanged("wallpaper_opacity") {
			setClauses = append(setClauses, "wallpaper_opacity = ?")
			values = append(values, t.Wallpaper_opacity)
		}
		if t.hasFieldChanged("wallpaper_blur") {
			setClauses = append(setClauses, "wallpaper_blur = ?")
			values = append(values, t.Wallpaper_blur)
		}
		if t.hasFieldChanged("panel_opacity") {
			setClauses = append(setClauses, "panel_opacity = ?")
			values = append(values, t.Panel_opacity)
		}
		if t.hasFieldChanged("font") {
			setClauses = append(setClauses, "font = ?")
			values = append(values, t.Font)
		}
		if t.hasFieldChanged("font_size") {
			setClauses = append(setClauses, "font_size = ?")
			values = append(values, t.Font_size)
		}
		if t.hasFieldChanged("density") {
			setClauses = append(setClauses, "density = ?")
			values = append(values, t.Density)
		}
		if t.hasFieldChanged("updated_at") {
			setClauses = append(setClauses, "updated_at = ?")
			values = append(values, t.Updated_at)
		}

		// If nothing changed, skip update
		if len(setClauses) == 0 {
			return true // No changes, success
		}
	} else {
		// No old values (fresh record), update all fields
		setClauses = append(setClauses, "light_theme = ?")
		values = append(values, t.Light_theme)
		setClauses = append(setClauses, "dark_theme = ?")
		values = append(values, t.Dark_theme)
		setClauses = append(setClauses, "mode = ?")
		values = append(values, t.Mode)
		setClauses = append(setClauses, "wallpaper = ?")
		values = append(values, t.Wallpaper)
		setClauses = append(setClauses, "wallpaper_opacity = ?")
		values = append(values, t.Wallpaper_opacity)
		setClauses = append(setClauses, "wallpaper_blur = ?")
		values = append(values, t.Wallpaper_blur)
		setClauses = append(setClauses, "panel_opacity = ?")
		values = append(values, t.Panel_opacity)
		setClauses = append(setClauses, "font = ?")
		values = append(values, t.Font)
		setClauses = append(setClauses, "font_size = ?")
		values = append(values, t.Font_size)
		setClauses = append(setClauses, "density = ?")
		values = append(values, t.Density)
		setClauses = append(setClauses, "updated_at = ?")
		values = append(values, t.Updated_at)
	}

	// Add WHERE clause value (primary key as loaded, so a renamed key still matches)
	if old, ok := t.oldValues["user_id"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.User_id)
	}

	// Build and execute SQL
	sqlStr := fmt.Sprintf(`UPDATE "%s" SET %s WHERE 1=1 AND user_id = ?`,
		tableName,
		strings.Join(setClauses, ", "),
	)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(values))

	_, err := t.exec().Exec(sqlStr, values...)
	if err != nil {
		fmt.Printf("Error: Failed to modify User_Personalization: %v\n", err)
		return false
	}
	// The stored record now matches the current values (including a renamed key)
	if t.oldValues != nil {
		t.StoreOldValues()
	}
	return true
}

// hasFieldChanged checks if a field value has changed from oldValues
func (t *UserPersonalization) hasFieldChanged(fieldName string) bool {
	if t.oldValues == nil {
		return true // No old values, assume changed
	}

	oldValue, exists := t.oldValues[fieldName]
	if !exists {
		return true // Field not in old values, assume changed
	}
	_ = oldValue // Suppress unused variable when all fields are PKs

	// Compare old vs new value based on field name (with type assertion)
	switch fieldName {
	case "user_id":
		if old, ok := oldValue.(types.Code); ok {
			return !t.User_id.Equal(old)
		}
	case "light_theme":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Light_theme.Equal(old)
		}
	case "dark_theme":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Dark_theme.Equal(old)
		}
	case "mode":
		if old, ok := oldValue.(UserPersonalizationMode); ok {
			return t.Mode != old
		}
	case "wallpaper":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Wallpaper.Equal(old)
		}
	case "wallpaper_opacity":
		if old, ok := oldValue.(int); ok {
			return t.Wallpaper_opacity != old
		}
		return true // Type mismatch, assume changed
	case "wallpaper_blur":
		if old, ok := oldValue.(int); ok {
			return t.Wallpaper_blur != old
		}
		return true // Type mismatch, assume changed
	case "panel_opacity":
		if old, ok := oldValue.(int); ok {
			return t.Panel_opacity != old
		}
		return true // Type mismatch, assume changed
	case "font":
		if old, ok := oldValue.(UserPersonalizationFont); ok {
			return t.Font != old
		}
	case "font_size":
		if old, ok := oldValue.(int); ok {
			return t.Font_size != old
		}
		return true // Type mismatch, assume changed
	case "density":
		if old, ok := oldValue.(UserPersonalizationDensity); ok {
			return t.Density != old
		}
	case "updated_at":
		if old, ok := oldValue.(types.DateTime); ok {
			return !t.Updated_at.Equal(old)
		}
	}

	return false
}

