// userPersonalizationFilterCondition represents a filter on a field
type userPersonalizationFilterCondition struct {
	fieldName    string
	minValue     interface{}
	maxValue     interface{}
	filterExpr   string // For complex SetFilter expressions
	isExpression bool   // True if using filterExpr instead of min/max
	invalidField bool   // Filter on an unknown field: matches no rows (fail closed)
}

// SetRange sets a range filter on a field
// Usage:
//
//	SetRange("No", "10000") - exact match (No = "10000")
//	SetRange("No", "10000", "20000") - range (No between "10000" and "20000")
//	SetRange("No") - removes the filter on the field
func (t *UserPersonalization) SetRange(fieldName string, values ...interface{}) {
	if t.filters == nil {
		t.filters = make(map[string]*userPersonalizationFilterCondition)
	}

	var minValue, maxValue interface{}

	switch len(values) {
	case 0:
		if column, ok := t.columnName(fieldName); ok {
			delete(t.filters, column)
		}
		delete(t.filters, fieldName)
		return
	case 1:
		// Exact match: SetRange("No", "10000")
		minValue = values[0]
		maxValue = values[0]
	case 2:
		// Range: SetRange("No", "10000", "20000")
		minValue = values[0]
		maxValue = values[1]
		// A blank date as the lower bound (SetRange(date, 0D, x)) is the start: blank dates are
		// stored as NULL, which no BETWEEN matches
		if d, ok := minValue.(types.Date); ok && d.IsZero() {
			minValue = nil
		}
	default:
		fmt.Printf("Error: SetRange requires 1 or 2 values, got %d\n", len(values))
		return
	}

	column, ok := t.columnName(fieldName)
	if !ok {
		// Unknown field: fail closed (no rows) rather than drop the filter or put
		// the name into SQL
		fmt.Printf("Error: SetRange on unknown field %q of User_Personalization\n", fieldName)
		t.filters[fieldName] = &userPersonalizationFilterCondition{invalidField: true}
		return
	}

	t.filters[column] = &userPersonalizationFilterCondition{
		fieldName: column,
		minValue:  minValue,
		maxValue:  maxValue,
	}
}

// SetFilter sets a complex filter expression on a field
// Supports filter syntax: "100..200|500" (range OR exact value)
// Operators: .. (range), | (OR), & (AND), * (wildcard), <> (not equal)
// Example: customer.SetFilter("No", "001..003|005")
func (t *UserPersonalization) SetFilter(fieldName, filterExpr string) {
	if t.filters == nil {
		t.filters = make(map[string]*userPersonalizationFilterCondition)
	}
	column, ok := t.columnName(fieldName)
	if !ok {
		// Unknown field: fail closed (no rows) rather than drop the filter or put
		// the name into SQL
		fmt.Printf("Error: SetFilter on unknown field %q of User_Personalization\n", fieldName)
		t.filters[fieldName] = &userPersonalizationFilterCondition{invalidField: true}
		return
	}
	t.filters[column] = &userPersonalizationFilterCondition{
		fieldName:    column,
		filterExpr:   filterExpr,
		isExpression: true,
	}
}

