// TestField returns an error unless the field has a value — or, with a value, that value
// (TestField): the user's messages "X is required" / "X must be …"
func (t *UserPersonalization) TestField(fieldName string, value ...any) error {
	no := t.FieldNo(fieldName)
	current, ok := t.FieldValue(no)
	if !ok {
		return fmt.Errorf("TestField: %s is not a stored field of User_Personalization", fieldName)
	}
	field := t.FieldName(no)
	if len(value) == 0 {
		if tables.IsEmptyValue(current) {
			return apperrors.FieldRequired(UserPersonalizationTableName, field)
		}
		return nil
	}
	if !tables.SameValue(current, value[0]) {
		return apperrors.FieldMustBe(UserPersonalizationTableName, field, fmt.Sprint(value[0]))
	}
	return nil
}

